def rob_linear(arr):
    prev, curr = 0, 0
    for n in arr:
        prev, curr = curr, max(curr, prev + n)
    return curr

def rob_circular(nums):
    if len(nums) == 1:
        return nums[0]
    return max(rob_linear(nums[1:]), rob_linear(nums[:-1]))    # exclude first, or exclude last

