public class Main {
    static int robLinear(int[] arr, int start, int end) {
        int prev = 0, curr = 0;
        for (int i = start; i < end; i++) {
            int next = Math.max(curr, prev + arr[i]);
            prev = curr;
            curr = next;
        }
        return curr;
    }

    static int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) return nums[0];
        return Math.max(robLinear(nums, 1, n), robLinear(nums, 0, n - 1));   // exclude first, or exclude last
    }
}

