int robLinear(vector<int>& arr, int start, int end) {
    int prev = 0, curr = 0;
    for (int i = start; i < end; i++) {
        int next = max(curr, prev + arr[i]);
        prev = curr;
        curr = next;
    }
    return curr;
}

int rob(vector<int>& nums) {
    int n = nums.size();
    if (n == 1) return nums[0];
    return max(robLinear(nums, 1, n), robLinear(nums, 0, n - 1));            // exclude first, or exclude last
}
